create extension if not exists pgcrypto;
create table if not exists artists(id uuid primary key default gen_random_uuid(),owner_user_id uuid,display_name text not null,handle text,slug text unique not null,bio text,notification_phone text,timezone text default 'America/New_York',brand jsonb default '{}'::jsonb,settings jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists tattoo_requests(id uuid primary key default gen_random_uuid(),artist_id uuid references artists(id) on delete cascade,request_code text unique not null,client_name text not null,phone text not null,email text,idea text not null,style text,placement text,size text,color text,budget text,preferred_timing text,reference_urls text,status text default 'new' check(status in ('new','needs_info','consultation','approved','deposit_pending','booked','completed','declined')),artist_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists appointments(id uuid primary key default gen_random_uuid(),request_id uuid references tattoo_requests(id) on delete cascade,artist_id uuid references artists(id) on delete cascade,starts_at timestamptz not null,ends_at timestamptz not null,status text default 'tentative',deposit_cents integer default 0,deposit_status text default 'unpaid',created_at timestamptz default now());
create table if not exists notification_log(id uuid primary key default gen_random_uuid(),artist_id uuid references artists(id),request_id uuid references tattoo_requests(id),channel text,status text,payload jsonb,created_at timestamptz default now());
insert into artists(display_name,handle,slug,bio) values ('Ayanna Luna','@inkbaby713','inkbaby713','Watercolor • Anime • Black & Grey • Flowers') on conflict(slug) do nothing;
